import{_ as a,o as n,c as s,a2 as e}from"./chunks/framework.D3fmyz3M.js";const u=JSON.parse('{"title":"选型决策树","description":"用一组可回答的问题，落到具体方案。","frontmatter":{"title":"选型决策树","description":"用一组可回答的问题，落到具体方案。"},"headers":[],"relativePath":"guide/decision-tree.md","filePath":"guide/decision-tree.md","lastUpdated":1792674288000}'),d={name:"guide/decision-tree.md"};function r(i,t,l,p,o,c){return n(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="选型决策树" tabindex="-1">选型决策树 <a class="header-anchor" href="#选型决策树" aria-label="Permalink to &quot;选型决策树&quot;">​</a></h1><p>先不要看 API，先回答四个问题：</p><ol><li>子应用需要<strong>独立运行</strong>吗？</li><li>需要<strong>强隔离</strong>吗？</li><li>团队能接受多高的<strong>改造与构建成本</strong>？</li><li>集成的是<strong>页面</strong>还是<strong>模块</strong>？</li></ol><h2 id="决策树" tabindex="-1">决策树 <a class="header-anchor" href="#决策树" aria-label="Permalink to &quot;决策树&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需要集成的是“组件/模块”而不是整页？</span></span>
<span class="line"><span>├─ 是 → 构建体系是否统一、可接受共享依赖？</span></span>
<span class="line"><span>│        ├─ 是 → Module Federation</span></span>
<span class="line"><span>│        └─ 否 → Web Components（标准组件）</span></span>
<span class="line"><span>└─ 否（整页应用）</span></span>
<span class="line"><span>   ├─ 子应用来自第三方 / 强安全边界？</span></span>
<span class="line"><span>   │   └─ 是 → iframe</span></span>
<span class="line"><span>   ├─ 需要浏览器级 JS 隔离，又要求页面内嵌体验？</span></span>
<span class="line"><span>   │   └─ 是 → wujie</span></span>
<span class="line"><span>   ├─ 子应用是 Vite / 现代构建，想少改代码？</span></span>
<span class="line"><span>   │   └─ 是 → micro-app</span></span>
<span class="line"><span>   ├─ 需要沙箱 + HTML Entry + 成熟生态？</span></span>
<span class="line"><span>   │   └─ 是 → qiankun</span></span>
<span class="line"><span>   └─ 只需要路由调度，隔离自己解决？</span></span>
<span class="line"><span>       └─ 是 → single-spa</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><h2 id="按场景对号入座" tabindex="-1">按场景对号入座 <a class="header-anchor" href="#按场景对号入座" aria-label="Permalink to &quot;按场景对号入座&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐</th><th>理由</th></tr></thead><tbody><tr><td>中后台整合，多团队 Vue/React 混合</td><td>qiankun</td><td>生态成熟，沙箱与样式隔离齐全</td></tr><tr><td>老系统渐进迁移，子应用不想改生命周期</td><td>micro-app</td><td>自定义标签接入，改造量小</td></tr><tr><td>需要强 JS 隔离但要求页面内嵌</td><td>wujie</td><td>iframe 执行 + Shadow DOM 渲染</td></tr><tr><td>第三方页面、强安全边界</td><td>iframe</td><td>浏览器级隔离，成本最低</td></tr><tr><td>设计系统 / 跨框架组件共享</td><td>Web Components</td><td>标准、可跨框架</td></tr><tr><td>构建体系统一，想共享组件与依赖</td><td>Module Federation</td><td>模块级共享，依赖去重</td></tr><tr><td>只想要一个轻量调度器</td><td>single-spa</td><td>抽象最小，自由度高</td></tr><tr><td>单体应用构建变慢，但团队只有一个</td><td>先拆包 / Monorepo</td><td>微前端收益不足</td></tr></tbody></table><h2 id="一张对比表-简版" tabindex="-1">一张对比表（简版） <a class="header-anchor" href="#一张对比表-简版" aria-label="Permalink to &quot;一张对比表（简版）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>JS 隔离</th><th>样式隔离</th><th>改造成本</th><th>体验</th><th>适合</th></tr></thead><tbody><tr><td>iframe</td><td>强</td><td>强</td><td>低</td><td>一般</td><td>第三方/强隔离</td></tr><tr><td>Web Components</td><td>弱</td><td>强</td><td>中</td><td>好</td><td>组件共享</td></tr><tr><td>single-spa</td><td>无</td><td>无</td><td>中</td><td>好</td><td>自建隔离</td></tr><tr><td>qiankun</td><td>强</td><td>中强</td><td>中</td><td>好</td><td>中后台</td></tr><tr><td>micro-app</td><td>强</td><td>强</td><td>低</td><td>好</td><td>Vite 子应用</td></tr><tr><td>wujie</td><td>强</td><td>强</td><td>低</td><td>好</td><td>强隔离 + 内嵌</td></tr><tr><td>Module Federation</td><td>无</td><td>无</td><td>高</td><td>好</td><td>模块共享</td></tr></tbody></table><p>完整维度见<a href="/micro-frontend-docs/appendix/matrix">方案对比矩阵</a>。</p><h2 id="选型时最该问的三个问题" tabindex="-1">选型时最该问的三个问题 <a class="header-anchor" href="#选型时最该问的三个问题" aria-label="Permalink to &quot;选型时最该问的三个问题&quot;">​</a></h2><h3 id="_1-谁来承担隔离成本" tabindex="-1">1. 谁来承担隔离成本？ <a class="header-anchor" href="#_1-谁来承担隔离成本" aria-label="Permalink to &quot;1. 谁来承担隔离成本？&quot;">​</a></h3><ul><li>方案自带隔离：qiankun、micro-app、wujie、iframe。</li><li>需要自己解决：single-spa、Module Federation、Web Components（JS 侧）。</li></ul><p>如果团队没有精力维护沙箱，选自带隔离的方案。</p><h3 id="_2-子应用能否改构建" tabindex="-1">2. 子应用能否改构建？ <a class="header-anchor" href="#_2-子应用能否改构建" aria-label="Permalink to &quot;2. 子应用能否改构建？&quot;">​</a></h3><ul><li>能改：全部方案都可行。</li><li>不能改：优先 iframe 或 wujie（对子应用侵入小）。</li></ul><p>qiankun 要求子应用输出 UMD；Module Federation 要求子应用接入联邦插件。这些都是构建层改造。</p><h3 id="_3-发布能否真正独立" tabindex="-1">3. 发布能否真正独立？ <a class="header-anchor" href="#_3-发布能否真正独立" aria-label="Permalink to &quot;3. 发布能否真正独立？&quot;">​</a></h3><p>如果子应用必须跟主应用一起发版，微前端的核心收益已经丢失。此时不如用 Monorepo + 统一构建。</p><h2 id="试点建议" tabindex="-1">试点建议 <a class="header-anchor" href="#试点建议" aria-label="Permalink to &quot;试点建议&quot;">​</a></h2><p>无论选哪个方案，第一版都建议：</p><ul><li>一个主应用 + 一个子应用。</li><li>只接一个边缘业务域。</li><li>打通构建、部署、监控、回滚。</li><li>用真实流量验证一个迭代。</li></ul><p>验证通过后再扩面。不要用“全量迁移”做第一次试点。</p><p>继续阅读：<a href="/micro-frontend-docs/schemes/">七个方案总览</a>。</p>`,24)])])}const b=a(d,[["render",r]]);export{u as __pageData,b as default};
